          "quote": "(net (code \"155\") (name \"Net-(D10-K)\") (node (ref \"D10\") (pin \"1\") (pinfunction \"K\") (pintype \"passive\")) (node (ref \"R60\") (pin \"2\") (pintype \"passive\")))"
